    Customer logos together with the key numbers: logos above the numbers, or beside them. Axes: layout (above, beside), logos (name, icon), tone, density.
    Props (p): id, title, logos, stats, layout, logoStyle, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_logos = ($p['logos'] ?? null)}
{var $v_stats = ($p['stats'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'above')}
{var $v_logoStyle = ($p['logoStyle'] ?? 'name')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_9}
  {capture $c_8}
    {capture $c_3}
      {foreach ui_l($v_logos) as $v_logo}
        {capture $c_2}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_logo, ['icon'])), 'Size' => 24]])|noescape}
          {capture $c_1}
            {=ui_text(ui_get($v_logo, ['name']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold', 'Class' => ui_s((ui_t(ui_eq($v_logoStyle, 'icon')) ? 'sr-only' : ''))], 'children' => $c_1])|noescape}
        {/capture}
        {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'center', 'Attrs' => ui_attrs(['data-testid', 'logo'])], 'children' => $c_2])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '6', 'Justify' => 'center', 'Class' => 'flex-wrap text-muted-foreground', 'Attrs' => ui_attrs(['data-testid', 'logos'])], 'children' => $c_3])|noescape}
    {capture $c_7}
      {foreach ui_l($v_stats) as $v_stat}
        {capture $c_6}
          {capture $c_4}
            {=ui_text(ui_get($v_stat, ['value']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => '4xl', 'Weight' => 'bold'], 'children' => $c_4])|noescape}
          {capture $c_5}
            {=ui_text(ui_get($v_stat, ['label']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_5])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0', 'Align' => 'center', 'Attrs' => ui_attrs(['data-testid', 'stat'])], 'children' => $c_6])|noescape}
      {/foreach}
    {/capture}
    {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_layout, 'beside')) ? '2' : '1-4')), 'Class' => 'gap-6 text-center', 'Attrs' => ui_attrs(['data-testid', 'stats'])], 'children' => $c_7])|noescape}
  {/capture}
  {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s((ui_t(ui_eq($v_layout, 'beside')) ? '1-2' : '1')), 'Class' => 'items-center gap-8'], 'children' => $c_8])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'tone' => $v_tone, 'density' => $v_density, 'align' => 'center', 'landmarkLabel' => $v_landmarkLabel], 'children' => $c_9])|noescape}
